package com.vandorlabs.vehicle;
import com.vandorlabs.coupler.*;
import java.util.*;
import java.util.concurrent.*;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.*;
import net.minecraft.tileentity.*;
import net.minecraft.util.*;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.WorldServer;
import net.minecraftforge.common.capabilities.*;
import net.minecraftforge.event.AttachCapabilitiesEvent;
import net.minecraftforge.event.entity.EntityJoinWorldEvent;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;
/** Test-only real assembly cancellation and WAL rollback. Never substitutes an in-memory transfer. */
public final class VehicleNativeReceiptRollbackChecks {
 private static final UUID OLD=new UUID(601,602),OLDGEN=new UUID(603,604);
 private static WorldServer world;private static VehicleScan scan;private static VehicleStructure original;private static BlockPos origin;private static int phase,ticks,checks,cancelCount,waited;private static Exception failure;private static EntityGroundVehicle success;private static Gate gate;private static CountDownLatch entered,release;private static Future<?> blocker;
 private static void need(boolean value,String why){checks++;if(!value)throw new IllegalStateException("native receipt rollback phase="+phase+" tick="+ticks+" "+why);}
 public static final class Opaque implements ICapabilitySerializable<NBTTagCompound>{private NBTTagCompound data=new NBTTagCompound();Opaque(){data.setString("FutureOpaque","native original");data.setIntArray("Contents",new int[]{9,7,11,3});}public boolean hasCapability(Capability<?> c,EnumFacing f){return false;}public <T>T getCapability(Capability<T> c,EnumFacing f){return null;}public NBTTagCompound serializeNBT(){return data.copy();}public void deserializeNBT(NBTTagCompound value){data=value.copy();}}
 public static final class Gate {
  boolean installing=true,cancel=true;UUID chosen;int attachments;
  @SubscribeEvent public void caps(AttachCapabilitiesEvent<TileEntity> event){if(installing&&(event.getObject() instanceof TileCoupler||event.getObject() instanceof TileEntityChest)){attachments++;event.addCapability(new ResourceLocation("vandorlabs","native_receipt_rollback_probe"),new Opaque());}}
  @SubscribeEvent public void join(EntityJoinWorldEvent event){if(event.getWorld()!=world||!(event.getEntity() instanceof EntityGroundVehicle))return;EntityGroundVehicle craft=(EntityGroundVehicle)event.getEntity();if(craft.structure==null||craft.posX<1800)return;chosen=craft.getUniqueID();need(craft.couplerAssociationGeneration()!=null,"chosen entity has real prospective scope before spawn");for(VehicleStructure.Cell cell:craft.structure.couplers){CouplerAssociation proof=CouplerAssociationData.read(cell.tileData());need(proof!=null&&proof.state==2&&proof.scope(cell.tileData().getUniqueId("CouplerControlIdentity"),chosen,craft.couplerAssociationGeneration()),"chosen entity carries new complete expected pair");}if(cancel){cancelCount++;need(world.isAirBlock(origin.add(original.couplers.get(0).pos)),"real WAL assembly removed native source before cancelled spawn");event.setCanceled(true);}}
 }
 public static void setup(WorldServer w,EntityPlayerMP actor){world=w;gate=new Gate();net.minecraftforge.common.MinecraftForge.EVENT_BUS.register(gate);VehicleArmCouplerFixture.setup(w,actor);for(int section=0;section<2;section++){BlockPos at=VehicleArmCouplerFixture.BASE.add(2,2,section==0?0:9);w.setBlockState(at,net.minecraft.init.Blocks.CHEST.getDefaultState(),2);TileEntityChest chest=(TileEntityChest)w.getTileEntity(at);chest.setCustomName("Native receipt original "+section);chest.setInventorySlotContents(0,new ItemStack(net.minecraft.init.Items.DIAMOND,section==0?7:11));}scan=new VehicleScan(w,VehicleArmCouplerFixture.BASE.add(VehicleArmCouplerFixture.SEAT));}
 private static void blockIO()throws Exception{java.lang.reflect.Field field=VehicleTransfer.class.getDeclaredField("IO");field.setAccessible(true);ExecutorService io=(ExecutorService)field.get(null);entered=new CountDownLatch(1);release=new CountDownLatch(1);blocker=io.submit(()->{entered.countDown();try{release.await();}catch(InterruptedException e){Thread.currentThread().interrupt();}});need(entered.await(5,TimeUnit.SECONDS),"real persistence worker blocked before WAL");}
 private static void submit(EntityPlayerMP actor)throws Exception{failure=null;success=null;waited=0;gate.chosen=null;blockIO();VehicleTransfer.submit(world,original,origin,()->success=VehicleTransfer.assemble(world,original,origin,actor),error->failure=error);}
 private static void capabilityBaseline(){int coupled=0,chests=0;for(VehicleStructure.Cell cell:original.cells){NBTTagCompound data=cell.tileData();if(cell.state.getBlock() instanceof BlockCoupler||cell.state.getBlock()==net.minecraft.init.Blocks.CHEST){need(data!=null&&data.getCompoundTag("ForgeCaps").hasKey("vandorlabs:native_receipt_rollback_probe",10),"actual native probe capability attached before transfer");if(cell.state.getBlock() instanceof BlockCoupler)coupled++;else chests++;}}need(gate.attachments>=4&&coupled==2&&chests==2,"positive capability attachment baseline for both heads and cargo owners");}
 private static void nativeOriginal(){need(original.matchesExact(world,origin),"all original native own fields/cargo/caps restored exactly");for(VehicleStructure.Cell cell:original.couplers){TileCoupler tile=(TileCoupler)world.getTileEntity(origin.add(cell.pos));NBTTagCompound actual=VehicleTileData.translated(tile.writeToNBT(new NBTTagCompound()),BlockPos.ORIGIN.subtract(origin));need(actual.equals(cell.tileData()),"native original proof/UUID/opaque exact, chosen receipt not left native");}int chests=0,diamonds=0;for(VehicleStructure.Cell cell:original.cells){TileEntity tile=world.getTileEntity(origin.add(cell.pos));if(tile instanceof TileEntityChest){chests++;ItemStack item=((TileEntityChest)tile).getStackInSlot(0);need(item.getItem()==net.minecraft.init.Items.DIAMOND,"original physical cargo type");diamonds+=item.getCount();}}need(chests==2&&diamonds==18,"two native cargo owners /18 diamonds");for(Entity e:world.loadedEntityList)if(e instanceof EntityGroundVehicle&&!e.isDead)need(e.posX<1800,"no usable chosen vehicle after cancelled publication");}
 private static void seedKnown(){int i=0;for(VehicleStructure.Cell cell:original.couplers){TileCoupler tile=(TileCoupler)world.getTileEntity(origin.add(cell.pos));NBTTagCompound data=tile.writeToNBT(new NBTTagCompound());UUID id=new UUID(610,++i);data.setUniqueId("CouplerControlIdentity",id);CouplerAssociationData.write(data,new CouplerAssociation(2,id,OLD,OLDGEN));tile.readFromNBT(data);}scan=new VehicleScan(world,VehicleArmCouplerFixture.BASE.add(VehicleArmCouplerFixture.SEAT));}
 public static boolean tick(EntityPlayerMP actor)throws Exception{
  need(++ticks<1200,"bounded actual WAL/rollback/retry");
  if(phase==0||phase==4){if(!scan.step(256))return false;need(scan.result!=null,"ordinary real native scan: "+scan.error);original=scan.result;origin=scan.origin;need(original.couplers.size()==2,"complete two-head physical source");capabilityBaseline();submit(actor);phase=phase==0?1:5;return false;}
  if(phase==1||phase==5||phase==8){if(release.getCount()>0){if(!VehicleTransfer.waitingForPersistence(world))return false;nativeOriginal();if(++waited<4)return false;release.countDown();blocker.get();return false;}if(VehicleTransfer.busy(world))return false;need(!VehicleTransfer.pending(world),"real transfer WAL/checkpoints retired");if(gate.cancel){need(failure!=null&&failure.toString().contains("spawn was cancelled")&&cancelCount==(phase==1?1:2),"actual EntityJoinWorld cancellation drives rollback: "+failure);need(success==null,"no returned usable vehicle after cancellation");nativeOriginal();if(phase==1){seedKnown();phase=4;return false;}gate.cancel=false;submit(actor);phase=8;return false;}
   need(failure==null&&success!=null&&!success.isDead&&!success.transferInProgress&&!success.ownershipBlocked,"successful actual retry has exactly one usable vehicle: "+failure);int vehicles=0;for(Entity e:world.loadedEntityList)if(e instanceof EntityGroundVehicle&&!e.isDead&&e.posX>1800)vehicles++;need(vehicles==1,"one chosen usable vehicle after retry");for(VehicleStructure.Cell cell:original.cells)need(world.isAirBlock(origin.add(cell.pos)),"native source retired once on successful retry");int diamonds=0,chests=0;for(VehicleStructure.Cell cell:success.structure.cells){NBTTagCompound data=cell.tileData();if(data!=null&&data.getString("id").equals("minecraft:chest")){need(data.getCompoundTag("ForgeCaps").getCompoundTag("vandorlabs:native_receipt_rollback_probe").equals(new Opaque().serializeNBT()),"chosen cargo opaque capability exact");NBTTagList items=data.getTagList("Items",10);for(int i=0;i<items.tagCount();i++)diamonds+=items.getCompoundTagAt(i).getByte("Count");chests++;}if(cell.state.getBlock() instanceof BlockCoupler){CouplerAssociation proof=CouplerAssociationData.read(data);need(proof!=null&&proof.vehicle.equals(success.getUniqueID())&&!proof.vehicle.equals(OLD),"retry chosen proof belongs only to new owner");need(data.getCompoundTag("ForgeCaps").getCompoundTag("vandorlabs:native_receipt_rollback_probe").equals(new Opaque().serializeNBT()),"opaque original capability envelope exact in chosen source");}}need(chests==2&&diamonds==18,"successful retry retains exact immutable cargo18");net.minecraftforge.common.MinecraftForge.EVENT_BUS.unregister(gate);System.out.println("[vandorlabs][reprolab] native-receipt-assembly-rollback PASS checks="+checks+" actual EntityJoinWorld cancel twice/asyncWAL4ticks native original exact absent+known proof UUID caps cargo18/new proof not native/successful retry one owner");return true;
  }return false;
 }
 private VehicleNativeReceiptRollbackChecks(){}
}
